{
  "extends": ["next/core-web-vitals", "next/typescript"]
}

@tailwind base;
@tailwind components;
@tailwind utilities;

:root {
  --paper: #fafaf7;
  --ink: #1a1a1a;
  --ink-muted: #4a4a4a;
  --paper-shade: #f0efea;
}

html {
  scroll-behavior: smooth;
}

html,
body {
  background: #fafaf7;
  color: #1a1a1a;
}

body {
  overflow-x: hidden;
}

::selection {
  background: #1a1a1a;
  color: #fafaf7;
}

section[id],
#top,
#main {
  scroll-margin-top: 5.5rem;
}

@media (prefers-reduced-motion: reduce) {
  html {
    scroll-behavior: auto;
  }
}

import type { Metadata } from "next";
import { Caveat, Inter } from "next/font/google";
import { PaperGrain } from "@/components/PaperGrain";
import { SketchFilter } from "@/components/SketchFilter";
import { site } from "@/config/site";
import "./globals.css";

const caveat = Caveat({
  subsets: ["latin"],
  weight: ["400", "600", "700"],
  variable: "--font-hand",
});

const inter = Inter({
  subsets: ["latin"],
  weight: ["400", "500"],
  variable: "--font-sans",
});

export const metadata: Metadata = {
  title: site.meta.title,
  description: site.meta.description,
};

export default function RootLayout({
  children,
}: Readonly<{
  children: React.ReactNode;
}>) {
  return (
    <html lang="en" className={`${caveat.variable} ${inter.variable}`}>
      <body className="bg-paper font-sans text-ink antialiased">
        <SketchFilter />
        <PaperGrain />
        <div className="relative z-[2]">{children}</div>
      </body>
    </html>
  );
}

import { FAQ } from "@/components/FAQ";
import { Features } from "@/components/Features";
import { FinalCta } from "@/components/FinalCta";
import { Footer } from "@/components/Footer";
import { Hero } from "@/components/Hero";
import { HowItWorks } from "@/components/HowItWorks";
import { LogoStrip } from "@/components/LogoStrip";
import { Nav } from "@/components/Nav";
import { Testimonials } from "@/components/Testimonials";
import { Work } from "@/components/Work";

export default function Home() {
  return (
    <div id="top">
      <a
        href="#main"
        className="sr-only focus:not-sr-only focus:absolute focus:left-4 focus:top-4 focus:z-20 focus:bg-paper focus:px-3 focus:py-2 focus:font-sans"
      >
        Skip to content
      </a>
      <Nav />
      <main id="main">
        <Hero />
        <LogoStrip />
        <Features />
        <HowItWorks />
        <Testimonials />
        <Work />
        <FAQ />
        <FinalCta />
      </main>
      <Footer />
    </div>
  );
}

"use client";

import { useState } from "react";
import { motion, useReducedMotion } from "framer-motion";
import { fadeUp, stagger } from "@/components/sketchMotion";
import { site } from "@/config/site";

export function FAQ() {
  const reduce = useReducedMotion();
  const [open, setOpen] = useState<number | null>(0);

  return (
    <section id="faq" className="px-4 py-20 md:px-6 md:py-28">
      <div className="mx-auto max-w-3xl">
        <h2 className="font-hand text-3xl font-bold tracking-tight md:text-5xl">
          {site.faq.title}
        </h2>
        <motion.ul
          className="mt-10 space-y-4"
          initial={reduce ? false : "hidden"}
          whileInView="show"
          viewport={{ once: true, margin: "-80px" }}
          variants={reduce ? undefined : stagger}
        >
          {site.faq.items.map((item, i) => {
            const isOpen = open === i;
            return (
              <motion.li key={item.q} variants={reduce ? undefined : fadeUp}>
                <div className="relative">
                  <span
                    aria-hidden
                    className="pointer-events-none absolute inset-0 border-2 border-ink"
                    style={{ filter: "url(#sketch-wobble)", borderRadius: 0 }}
                  />
                  <button
                    type="button"
                    className="relative flex w-full items-start justify-between gap-4 px-5 py-4 text-left"
                    aria-expanded={isOpen}
                    onClick={() => setOpen(isOpen ? null : i)}
                  >
                    <span className="font-hand text-2xl leading-tight">{item.q}</span>
                    <span className="font-hand text-3xl leading-none" aria-hidden>
                      {isOpen ? "−" : "+"}
                    </span>
                  </button>
                  {isOpen && (
                    <p className="relative px-5 pb-5 font-sans text-base leading-relaxed text-ink-muted">
                      {item.a}
                    </p>
                  )}
                </div>
              </motion.li>
            );
          })}
        </motion.ul>
      </div>
    </section>
  );
}

"use client";

import { motion, useReducedMotion } from "framer-motion";
import { Doodle, type DoodleKey } from "@/components/doodles";
import { SketchBox } from "@/components/SketchBox";
import { fadeUp, stagger } from "@/components/sketchMotion";
import { site } from "@/config/site";

export function Features() {
  const reduce = useReducedMotion();

  return (
    <section id="craft" className="px-4 py-20 md:px-6 md:py-28">
      <div className="mx-auto max-w-6xl">
        <h2 className="max-w-[16ch] font-hand text-3xl font-bold tracking-tight md:text-5xl">
          {site.features.title}
        </h2>
        <motion.ul
          className="mt-12 grid grid-cols-1 gap-6 md:grid-cols-2 lg:grid-cols-3"
          initial={reduce ? false : "hidden"}
          whileInView="show"
          viewport={{ once: true, margin: "-80px" }}
          variants={reduce ? undefined : stagger}
        >
          {site.features.items.map((feature) => (
            <motion.li key={feature.title} variants={reduce ? undefined : fadeUp}>
              <SketchBox className="h-full p-6" wiggleOnHover>
                <Doodle name={feature.doodle as DoodleKey} />
                <h3 className="mt-4 font-hand text-2xl font-semibold leading-tight md:text-3xl">
                  {feature.title}
                </h3>
                <p className="mt-2 font-sans text-base leading-relaxed text-ink-muted">
                  {feature.benefit}
                </p>
              </SketchBox>
            </motion.li>
          ))}
        </motion.ul>
      </div>
    </section>
  );
}

"use client";

import { motion, useReducedMotion } from "framer-motion";
import { SketchBox } from "@/components/SketchBox";
import { SketchButton } from "@/components/SketchButton";
import { fadeUp } from "@/components/sketchMotion";
import { site } from "@/config/site";

export function FinalCta() {
  const reduce = useReducedMotion();

  return (
    <section id="contact" className="bg-paper-shade px-4 py-20 md:px-6 md:py-28">
      <motion.div
        className="mx-auto max-w-3xl"
        initial={reduce ? false : "hidden"}
        whileInView="show"
        viewport={{ once: true, margin: "-80px" }}
        variants={reduce ? undefined : fadeUp}
      >
        <SketchBox className="px-6 py-12 text-center md:px-12 md:py-16" shadow={6}>
          <h2 className="font-hand text-3xl font-bold tracking-tight md:text-5xl">
            {site.cta.headline}
          </h2>
          <p className="mx-auto mt-4 max-w-[42ch] font-sans text-base leading-relaxed text-ink-muted">
            {site.cta.sub}
          </p>
          <div className="mt-8 flex flex-col items-center justify-center gap-4 sm:flex-row">
            <SketchButton href={`mailto:${site.identity.email}`}>
              {site.cta.primary}
            </SketchButton>
