import { FoldedCornerDoodle } from "@/components/doodles";
import { site } from "@/config/site";

export function Footer() {
  return (
    <footer className="px-4 py-14 md:px-6 md:py-16">
      <div className="mx-auto max-w-6xl">
        <div className="grid grid-cols-1 gap-10 md:grid-cols-3">
          <div>
            <a href="#top" className="inline-flex items-center gap-2 text-ink">
              <FoldedCornerDoodle className="h-5 w-5" />
              <span className="font-hand text-2xl leading-none">
                {site.identity.monogram}
              </span>
            </a>
            <p className="mt-3 max-w-[32ch] font-sans text-sm leading-relaxed text-ink-muted">
              {site.footer.descriptor}
            </p>
          </div>
          {site.footer.clusters.map((cluster) => (
            <div key={cluster.title}>
              <p className="font-hand text-xl">{cluster.title}</p>
              <ul className="mt-3 space-y-2 font-sans text-sm">
                {cluster.links.map((link) => (
                  <li key={link.href}>
                    <a
                      href={link.href}
                      className="underline underline-offset-2"
                      {...("external" in link && link.external
                        ? { target: "_blank", rel: "noopener noreferrer" }
                        : {})}
                    >
                      {link.label}
                    </a>
                  </li>
                ))}
              </ul>
            </div>
          ))}
        </div>
        <p className="mt-12 font-sans text-sm text-ink-muted">{site.footer.legal}</p>
      </div>
    </footer>
  );
}

"use client";

import { motion, useReducedMotion } from "framer-motion";
import { CheckDoodle, UnderlineScribble } from "@/components/doodles";
import { SketchBox } from "@/components/SketchBox";
import { SketchButton } from "@/components/SketchButton";
import { fadeUp } from "@/components/sketchMotion";
import { site } from "@/config/site";

export function Hero() {
  const reduce = useReducedMotion();
  const variants = reduce ? undefined : fadeUp;
  const { hero, identity } = site;

  return (
    <section className="px-4 py-14 md:px-6 md:py-20">
      <div className="mx-auto grid max-w-6xl items-center gap-10 lg:grid-cols-2 lg:gap-14">
        <motion.div
          initial={reduce ? false : "hidden"}
          animate="show"
          variants={variants}
        >
          <p className="font-hand text-xl text-ink-muted">{hero.eyebrow}</p>
          <h1 className="mt-3 font-hand text-4xl font-bold leading-[1.1] tracking-tight md:text-6xl lg:text-7xl">
            {hero.headline}
          </h1>
          <UnderlineScribble className="mt-2 h-3 w-48 md:w-72" />
          <p className="mt-5 max-w-[48ch] font-sans text-base leading-relaxed text-ink-muted">
            {hero.subhead}
          </p>
          <p className="mt-3 font-hand text-xl text-ink">
            {identity.name} · {identity.role}
          </p>
          <div className="mt-8 flex flex-wrap items-center gap-4">
            <SketchButton href={hero.primaryHref}>{hero.primaryCta}</SketchButton>
            <SketchButton href={hero.secondaryHref} variant="secondary">
              {hero.secondaryCta}
            </SketchButton>
          </div>
        </motion.div>
        <motion.div
          initial={reduce ? false : { opacity: 0, y: 24 }}
          animate={{ opacity: 1, y: 0 }}
          transition={{ duration: 0.55, delay: 0.12, ease: [0.22, 1, 0.36, 1] }}
          className="mx-auto w-full max-w-sm lg:max-w-none"
        >
          <SketchBox className="p-6 md:p-8" shadow={6}>
            <p className="font-hand text-xl text-ink-muted">{hero.aside.kicker}</p>
            <ul className="mt-5 space-y-3">
              {hero.aside.notes.map((note) => (
                <li key={note.text} className="flex items-center gap-3">
                  <CheckDoodle
                    className={`h-5 w-5 shrink-0 ${note.checked ? "text-ink" : "text-ink-muted opacity-40"}`}
                  />
                  <span
                    className={`font-hand text-2xl leading-none ${note.checked ? "text-ink" : "text-ink-muted"}`}
                  >
                    {note.text}
                  </span>
                </li>
              ))}
            </ul>
            <p className="mt-8 rotate-[-2deg] font-hand text-3xl font-semibold">
              {hero.aside.stamp}
            </p>
          </SketchBox>
        </motion.div>
      </div>
    </section>
  );
}

"use client";

import { motion, useReducedMotion } from "framer-motion";
import { ArrowScribble, Doodle, type DoodleKey } from "@/components/doodles";
import { fadeUp, stagger } from "@/components/sketchMotion";
import { site } from "@/config/site";

export function HowItWorks() {
  const reduce = useReducedMotion();

  return (
    <section id="how-it-works" className="bg-paper-shade px-4 py-20 md:px-6 md:py-28">
      <div className="mx-auto max-w-6xl">
        <h2 className="max-w-[22ch] font-hand text-3xl font-bold tracking-tight md:text-5xl">
          {site.howItWorks.title}
        </h2>
        <motion.ol
          className="mt-12 grid grid-cols-1 gap-10 md:grid-cols-3 md:gap-6"
          initial={reduce ? false : "hidden"}
          whileInView="show"
          viewport={{ once: true, margin: "-80px" }}
          variants={reduce ? undefined : stagger}
        >
          {site.howItWorks.steps.map((step, i) => (
            <motion.li
              key={step.n}
              className="relative"
              variants={reduce ? undefined : fadeUp}
            >
              {i < site.howItWorks.steps.length - 1 && (
                <ArrowScribble className="pointer-events-none absolute -right-8 top-6 hidden h-8 w-14 text-ink md:block" />
              )}
              <Doodle name={step.doodle as DoodleKey} className="h-9 w-9 text-ink" />
              <p className="mt-5 font-hand text-4xl leading-none text-ink">{step.n}</p>
              <h3 className="mt-3 font-hand text-3xl font-semibold">{step.title}</h3>
              <p className="mt-2 max-w-[36ch] font-sans text-base leading-relaxed text-ink-muted">
                {step.body}
              </p>
            </motion.li>
          ))}
        </motion.ol>
      </div>
    </section>
  );
}

"use client";

import { motion, useReducedMotion } from "framer-motion";
import { fadeUp, stagger, wiggle } from "@/components/sketchMotion";
import { site } from "@/config/site";

export function LogoStrip() {
  const reduce = useReducedMotion();

  return (
    <section className="bg-paper-shade px-4 py-14 md:px-6 md:py-16">
      <div className="mx-auto max-w-6xl">
        <p className="text-center font-hand text-2xl text-ink-muted md:text-3xl">
          {site.logos.label}
        </p>
        <motion.ul
          className="mt-8 flex flex-wrap items-center justify-center gap-x-10 gap-y-4"
