"use client";

import { useState } from "react";
import { motion, useReducedMotion } from "framer-motion";
import { FoldedCornerDoodle } from "@/components/doodles";
import { SketchButton } from "@/components/SketchButton";
import { wiggle } from "@/components/sketchMotion";
import { site } from "@/config/site";

export function Nav() {
  const reduce = useReducedMotion();
  const [open, setOpen] = useState(false);

  return (
    <header className="relative sticky top-0 z-10 bg-paper">
      <div className="relative mx-auto flex max-w-6xl items-center justify-between gap-4 px-4 py-3 md:px-6">
        <a href="#top" className="flex items-center gap-2 text-ink">
          <FoldedCornerDoodle className="h-5 w-5" />
          <span className="font-hand text-2xl leading-none">
            {site.identity.monogram}
          </span>
        </a>
        <nav className="hidden items-center gap-6 md:flex" aria-label="Primary">
          {site.nav.links.map((link) => (
            <motion.a
              key={link.href}
              href={link.href}
              className="font-hand text-xl leading-none text-ink underline decoration-transparent underline-offset-4 hover:decoration-ink"
              variants={reduce ? undefined : wiggle}
              initial="rest"
              animate="rest"
              whileHover={reduce ? undefined : "hover"}
            >
              {link.label}
            </motion.a>
          ))}
        </nav>
        <div className="flex items-center gap-2">
          <button
            type="button"
            className="relative px-3 py-2 font-hand text-xl md:hidden"
            aria-expanded={open}
            aria-controls="mobile-nav"
            onClick={() => setOpen((v) => !v)}
          >
            <span
              aria-hidden
              className="pointer-events-none absolute inset-0 border-2 border-ink"
              style={{ filter: "url(#sketch-wobble)" }}
            />
            <span className="relative">{open ? "Close" : "Menu"}</span>
          </button>
          <SketchButton
            href={`mailto:${site.identity.email}`}
            className="px-5 py-2 text-xl md:px-6"
          >
            {site.nav.cta}
          </SketchButton>
        </div>
      </div>
      {open && (
        <nav
          id="mobile-nav"
          className="grid gap-3 px-4 pb-4 md:hidden"
          aria-label="Mobile"
        >
          {site.nav.links.map((link) => (
            <a
              key={link.href}
              href={link.href}
              className="font-hand text-2xl text-ink underline underline-offset-4"
              onClick={() => setOpen(false)}
            >
              {link.label}
            </a>
          ))}
        </nav>
      )}
      <span
        aria-hidden
        className="pointer-events-none absolute inset-x-0 bottom-0 h-[2px] bg-ink"
        style={{ filter: "url(#sketch-wobble)" }}
      />
    </header>
  );
}

export function PaperGrain() {
  return (
    <div
      aria-hidden
      className="pointer-events-none fixed inset-0 z-[1] opacity-[0.045]"
      style={{
        backgroundImage: `url("data:image/svg+xml,%3Csvg viewBox='0 0 200 200' xmlns='http://www.w3.org/2000/svg'%3E%3Cfilter id='n'%3E%3CfeTurbulence type='fractalNoise' baseFrequency='0.85' numOctaves='4' stitchTiles='stitch'/%3E%3C/filter%3E%3Crect width='100%25' height='100%25' filter='url(%23n)'/%3E%3C/svg%3E")`,
        backgroundRepeat: "repeat",
        backgroundSize: "180px 180px",
      }}
    />
  );
}

"use client";

import { motion, useReducedMotion } from "framer-motion";
import { wiggle } from "@/components/sketchMotion";

export function SketchBox({
  children,
  className = "",
  shadow = 4,
  wiggleOnHover = false,
}: {
  children: React.ReactNode;
  className?: string;
  shadow?: 4 | 6;
  wiggleOnHover?: boolean;
}) {
  const reduce = useReducedMotion();
  const offset =
    shadow === 6
      ? "translate-x-[6px] translate-y-[6px]"
      : "translate-x-[4px] translate-y-[4px]";

  const inner = (
    <div className={`relative bg-paper ${className}`}>
      <span
        aria-hidden
        className={`pointer-events-none absolute inset-0 bg-ink ${offset}`}
        style={{ filter: "url(#sketch-wobble)" }}
      />
      <span aria-hidden className="pointer-events-none absolute inset-0 bg-paper" />
      <span
        aria-hidden
        className="pointer-events-none absolute inset-0 border-2 border-ink"
        style={{ filter: "url(#sketch-wobble)", borderRadius: 0 }}
      />
      <div className="relative z-[1]">{children}</div>
    </div>
  );

  if (!wiggleOnHover || reduce) {
    return inner;
  }

  return (
    <motion.div
      className="relative h-full"
      variants={wiggle}
      initial="rest"
      animate="rest"
      whileHover="hover"
    >
      {inner}
    </motion.div>
  );
}

"use client";

import { motion, useReducedMotion } from "framer-motion";
import { wiggle } from "@/components/sketchMotion";

type Props = {
  children: React.ReactNode;
  variant?: "primary" | "secondary";
  className?: string;
  href?: string;
  target?: string;
  rel?: string;
  type?: "button" | "submit" | "reset";
  onClick?: React.MouseEventHandler<HTMLButtonElement>;
};

export function SketchButton({
  children,
  variant = "primary",
  className = "",
  href,
  target,
  rel,
  type = "button",
  onClick,
}: Props) {
  const reduce = useReducedMotion();
  const filled = variant === "primary";

  const face = (
    <>
      {filled && (
        <span
          aria-hidden
          className="absolute inset-0 bg-ink"
          style={{ filter: "url(#sketch-wobble)" }}
        />
      )}
      <span
        aria-hidden
        className="pointer-events-none absolute inset-0 border-2 border-ink"
        style={{ filter: "url(#sketch-wobble)" }}
      />
      <span
        aria-hidden
        className="pointer-events-none absolute inset-[4px] border border-ink"
        style={{
          filter: "url(#sketch-wobble)",
          borderColor: filled ? "#FAFAF7" : "#1A1A1A",
        }}
      />
      <span className={`relative ${filled ? "text-paper" : "text-ink"}`}>
        {children}
      </span>
    </>
  );

  const classes = `group relative inline-flex items-center justify-center px-7 py-3 font-hand text-2xl leading-none ${className}`;

  if (href) {
    return (
      <motion.a
        href={href}
        target={target}
        rel={rel}
        className={classes}
        variants={reduce ? undefined : wiggle}
        initial="rest"
        animate="rest"
        whileHover={reduce ? undefined : "hover"}
      >
        {face}
      </motion.a>
    );
  }

  return (
    <motion.button
      type={type}
      onClick={onClick}
      className={classes}
      variants={reduce ? undefined : wiggle}
      initial="rest"
      animate="rest"
      whileHover={reduce ? undefined : "hover"}
    >
      {face}
    </motion.button>
  );
}

"use client";

import { motion, useReducedMotion } from "framer-motion";
import { SketchBox } from "@/components/SketchBox";
import { fadeUp, stagger } from "@/components/sketchMotion";
import { site } from "@/config/site";

export function Testimonials() {
  const reduce = useReducedMotion();

  return (
    <section className="px-4 py-20 md:px-6 md:py-28">
      <div className="mx-auto max-w-6xl">
        <h2 className="font-hand text-3xl font-bold tracking-tight md:text-5xl">
          {site.testimonials.title}
        </h2>
        <motion.ul
          className="mt-12 grid grid-cols-1 gap-6 lg:grid-cols-3"
          initial={reduce ? false : "hidden"}
          whileInView="show"
          viewport={{ once: true, margin: "-80px" }}
          variants={reduce ? undefined : stagger}
        >
          {site.testimonials.items.map((item) => (
            <motion.li key={item.name} variants={reduce ? undefined : fadeUp}>
              <SketchBox className="h-full p-6" wiggleOnHover>
                <p className="font-sans text-base leading-relaxed text-ink">
                  &ldquo;{item.quote}&rdquo;
                </p>
                <div className="mt-5 flex items-center gap-3">
                  <span
                    className="relative flex h-10 w-10 items-center justify-center font-hand text-lg"
                    aria-hidden
                  >
                    <span
                      className="absolute inset-0 border-2 border-ink"
                      style={{
                        filter: "url(#sketch-wobble)",
                        borderRadius: "999px",
